function parseCorrections(markdown) {
  const startMatch = markdown.match(/^## Correction Notices\s*$/m);
  const ledgerMatch = markdown.match(/^## Transaction Ledger\s*$/m);
  const slice =
    startMatch && ledgerMatch && ledgerMatch.index > startMatch.index
      ? markdown.slice(startMatch.index, ledgerMatch.index)
      : "";

  const notices = [];
  const blocks = slice.split(/^### /m).slice(1);
  for (const block of blocks) {
    const lines = block.split("\n");
    const noticeId = lines[0].trim();
    if (!noticeId.startsWith("CORR-")) continue;

    const entry = { notice_id: noticeId };
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("targets:")) entry.transaction_id = trimmed.split(":")[1].trim();
      else if (trimmed.startsWith("field:")) entry.field = trimmed.split(":")[1].trim();
      else if (trimmed.startsWith("value:")) entry.value = trimmed.split(":")[1].trim();
      else if (trimmed.startsWith("effective:")) entry.effective = trimmed.split(":")[1].trim();
    }

    if (entry.transaction_id && entry.field && entry.effective) notices.push(entry);
  }
  return notices;
}

module.exports = { parseCorrections };
EOF

