function validateOutputs(items, exceptions, report) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new Error("no transactions produced");
  }
  if (!Array.isArray(exceptions)) {
    throw new Error("invalid exceptions");
  }
  if (!Array.isArray(report)) {
    throw new Error("invalid report");
  }

  const requiredFields = [
    "transaction_id",
    "owner",
    "status",
    "effective_date",
    "amount_usd",
    "exception_reason",
  ];
  for (const row of items) {
    for (const f of requiredFields) {
      if (!(f in row)) throw new Error(`missing field ${f}`);
    }
  }

  for (let i = 1; i < items.length; i += 1) {
    if (items[i - 1].transaction_id > items[i].transaction_id) {
      throw new Error("transactions not sorted");
    }
  }
}

module.exports = { validateOutputs };
EOF
